WITH exploded AS (SELECT id, created_at, coupon_codes, li_item.product_id, li_item.qty FROM carts LATERAL VIEW OUTER EXPLODE(items) x AS li_item), filtered AS (SELECT coupon_codes, product_id, ARRAY_JOIN(coupon_codes, ', ') AS coupon_codes_text FROM exploded WHERE created_at < '2025-04-01'), filtered_carts AS (SELECT *, ARRAY_CONTAINS(coupon_codes, 'BUNDLE') AS is_bundle FROM filtered WHERE product_id BETWEEN 5 AND 9), filtered_carts_2 AS (SELECT *, ARRAY_JOIN(coupon_codes, '|') AS coupon_codes_text_2 FROM filtered_carts WHERE product_id >= 9) SELECT coupon_codes, product_id, coupon_codes_text, is_bundle, coupon_codes_text_2, DENSE_RANK() OVER (ORDER BY product_id DESC NULLS FIRST) AS product_id_dense_rank, PERCENT_RANK() OVER w_ordered AS product_id_percent_rank FROM filtered_carts_2 WHERE NOT is_bundle WINDOW w_ordered AS (ORDER BY product_id ASC)
